            #binding-cells = <2>;
            flavor = "tap-preferred";
            tapping-term-ms = <200>;
            quick-tap-ms = <200>;
            bindings = <&kp>, <&kp>;
        };
    };

    keymap {
        compatible = "zmk,keymap";
        label ="Default keymap";

        default_layer {
            bindings = <
                &tp_long LEFT_SHIFT F &tp_short LEFT_CONTROL J
                &kp D &kp RIGHT_CONTROL>;
        };
    };
};


