                      <option value="NICEVIEW">nice!view</option>
                    </select>
                  </div>
                )}
              </div>
            </div>
          </div>
          {split ? (
            <>
              <PowerEstimate
                board={currentBoard}
                splitType="central"
                batteryMilliAh={batteryMilliAh}
                usage={{ bondedQty, percentAsleep }}
                underglow={{ glowEnabled, glowBrightness, glowQuantity }}
                backlight={{
                  backlightEnabled,
                  backlightVoltage: currentBacklightVoltage,
                  backlightResistance,
                  backlightBrightness,
