  "oneOf": [
    {
      "$ref": "#/$defs/board"
    },
    {
      "$ref": "#/$defs/shield"
    },
    {
      "$ref": "#/$defs/interconnect"
    }
  ],
  "$defs": {
    "id": {
      "type": "string",
      "pattern": "^[a-z0-9_]+$"
    },
    "keyboard_siblings": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "variant": {
      "oneOf": [
        {
          "type": "string"
        },
        {
          "type": "object",
          "required": ["id", "features"],
          "properties": {
            "id": {
              "$ref": "#/$defs/id"
            },
            "features": {
              "$ref": "#/$defs/features"
            }
          }
        }
      ]
    },
    "features": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "keys",
          "display",
          "encoder",
          "underglow",
          "backlight",
          "pointer"
        ]
      }
    },
    "interconnects": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/id"
      }
    },
    "sibling_details": {
      "type": "object",
