        "uart": { "type": "string" },
        "adc": { "type": "string" }
      }
    },
    "interconnect": {
      "title": "Interconnect",
      "type": "object",
      "additionalProperties": false,
      "required": ["file_format", "id", "name", "description", "url", "type"],
      "properties": {
        "file_format": {
          "type": "string",
          "const": "1"
        },
        "id": {
          "$ref": "#/$defs/id"
        },
