      "additionalProperties": false,
      "required": [
        "file_format",
        "id",
        "name",
        "url",
        "arch",
        "type",
        "outputs"
      ],
      "properties": {
        "file_format": {
          "type": "string",
          "const": "1"
        },
        "id": {
          "$ref": "#/$defs/id"
        },
        "name": {
          "type": "string"
        },
        "version": {
          "type": "string"
        },
